def run(cc, spec, default_note="court tier not classifiable from name"):
    bodies = [(b[0], b[1], b[2], b[3], b[5] if len(b) > 5 else {}) for b in spec]
    rx = [(b[0], re.compile(b[4], re.I)) for b in spec if b[4]]
    def classify(n):
        for bid, r in rx:
            if r.search(n): return bid
    common(cc, bodies, classify, default_note=default_note)
def S(cc, spec, notes=None):
    def f(): run(cc, spec)
    return f
